'use strict';

// Text utilities. Small on purpose: the interesting part is the backlog, not the code.

const ACRONYMS = new Set(['API', 'HTTP', 'SQL', 'URL', 'CSS']);

// Cyrillic -> Latin, applied after lowercasing so only lowercase keys are needed.
// Russian, plus the Ukrainian/Belarusian letters that otherwise vanish silently.
const TRANSLITERATIONS = {
  а: 'a', б: 'b', в: 'v', г: 'g', д: 'd', е: 'e', ё: 'yo', ж: 'zh', з: 'z',
  и: 'i', й: 'y', к: 'k', л: 'l', м: 'm', н: 'n', о: 'o', п: 'p', р: 'r',
  с: 's', т: 't', у: 'u', ф: 'f', х: 'kh', ц: 'ts', ч: 'ch', ш: 'sh',
  щ: 'shch', ъ: '', ы: 'y', ь: '', э: 'e', ю: 'yu', я: 'ya',
  і: 'i', ї: 'yi', є: 'ye', ґ: 'g', ў: 'u',
};

function transliterate(s) {
  let out = '';
  for (const ch of s) out += ch in TRANSLITERATIONS ? TRANSLITERATIONS[ch] : ch;
  return out;
}

function slugify(input) {
  return transliterate(String(input).trim().toLowerCase())
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function truncate(input, maxLength, suffix = '…', { wordBoundary = false } = {}) {
  const s = String(input);
  if (s.length <= maxLength) return s;
  const head = s.slice(0, Math.max(0, maxLength - suffix.length));
  if (!wordBoundary) return head + suffix;
  // Back up to the last whitespace that still fits. If the cut already landed on a boundary
  // (the next character is whitespace) the head is kept whole.
  const atBoundary = /\s/.test(s[head.length]);
  const trimmed = atBoundary ? head.trimEnd() : head.replace(/\s*\S*$/, '');
  // A single word longer than the budget has no boundary to back up to — keep the hard cut.
  return (trimmed || head) + suffix;
}

function capitalize(input) {
  const s = String(input);
  if (!s) return s;
  return s[0].toUpperCase() + s.slice(1);
}

// Reduce markdown to the text a reader actually sees, so it can be counted.
// Link text survives, the URL does not; syntax markers leave nothing behind.
function stripMarkdown(input) {
  return String(input)
    .replace(/^\s*```.*$/gm, ' ') // code fences: the fence is syntax, the code inside is text
    .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ') // images render as a picture, not as words
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1') // inline link -> its text
    .replace(/\[([^\]]*)\]\[[^\]]*\]/g, '$1') // reference link -> its text
    .replace(/^\s{0,3}#{1,6}\s+/gm, '') // heading hashes
    .replace(/^\s*>+\s?/gm, '') // blockquote markers
    .replace(/^\s*([-*+]|\d+[.)])\s+/gm, '') // list bullets and numbers
    .replace(/^\s*([-*_])\1{2,}\s*$/gm, ' ') // horizontal rules
    .replace(/[*_~`]/g, ''); // emphasis, strikethrough and inline-code markers
}

function wordCount(input) {
  const s = stripMarkdown(input).trim();
  if (!s) return 0;
  return s.split(/\s+/).length;
}

const HTML_ENTITIES = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };

// One pass over the input, so the '&' an entity introduces is never re-escaped: the ampersand is
// handled first by construction rather than by ordering separate replace() calls.
// &#39; rather than &apos; — &apos; is not defined in HTML 4.
function escapeHtml(input) {
  return String(input).replace(/[&<>"']/g, (ch) => HTML_ENTITIES[ch]);
}

const WORDS_PER_MINUTE = 200;

// Whole minutes, rounded up — a part-read minute is still a minute the reader spends.
// Anything with visible content is at least 1, so a short note never reads as "0 min".
function readingTime(input) {
  const s = String(input);
  if (!s.trim()) return 0;
  return Math.max(1, Math.ceil(wordCount(s) / WORDS_PER_MINUTE));
}

function titleCase(input) {
  return String(input)
    .split(/\s+/)
    .map((w) => (ACRONYMS.has(w.toUpperCase()) ? w.toUpperCase() : capitalize(w.toLowerCase())))
    .join(' ');
}

module.exports = {
  slugify,
  truncate,
  capitalize,
  wordCount,
  readingTime,
  escapeHtml,
  titleCase,
  ACRONYMS,
};

