test('already-done-capitalize: first character up, rest untouched, empty is safe', () => {
  assert.strictEqual(capitalize('word'), 'Word');
  // "leave the rest alone" — inner capitals and casing survive.
  assert.strictEqual(capitalize('hELLO wORLD'), 'HELLO wORLD');
  assert.strictEqual(capitalize('iPhone'), 'IPhone');
  // Already uppercase, and a non-letter first character: both are no-ops, not errors.
  assert.strictEqual(capitalize('Word'), 'Word');
  assert.strictEqual(capitalize('123 go'), '123 go');
  assert.strictEqual(capitalize(' leading space'), ' leading space');
  // Empty string does not throw.
  assert.doesNotThrow(() => capitalize(''));
  assert.strictEqual(capitalize(''), '');
});

