  assert.strictEqual(wordCount('# Heading one'), 2);
  assert.strictEqual(wordCount('- item one\n- item two'), 4);
  assert.strictEqual(wordCount('1. first item\n2. second item'), 4);
  assert.strictEqual(wordCount('> quoted words here'), 3);
  assert.strictEqual(wordCount('a\n\n---\n\nb'), 2);
  // Code is text a reader reads; the backticks and fences are not.
  assert.strictEqual(wordCount('`code` sample'), 2);
  assert.strictEqual(wordCount('```js\nconst a = 1\n```'), 4);
  // An image renders as a picture: neither the alt text nor the URL is read.
  assert.strictEqual(wordCount('![alt text](img.png) caption'), 1);
  // A realistic paragraph.
  assert.strictEqual(
    // Intro | The API is documented at our site.
    wordCount('## Intro\n\nThe **API** is documented at [our site](https://example.com).'),
    8
  );
});

test('reading-time: whole minutes at 200 wpm, minimum 1 for non-empty text', () => {
  assert.strictEqual(readingTime(''), 0);
  assert.strictEqual(readingTime('   '), 0);
  assert.strictEqual(readingTime('one two three'), 1);
  assert.strictEqual(readingTime(words(200)), 1);
  assert.strictEqual(readingTime(words(201)), 2);
  assert.strictEqual(readingTime(words(400)), 2);
  assert.strictEqual(readingTime(words(401)), 3);
  // Counts what a reader sees: a long URL is not reading time.
  assert.strictEqual(readingTime('[a](https://example.com/a/very/long/path/that/is/not/read)'), 1);
});

test('escape-html: escapes the five characters, ampersand first', () => {
  assert.strictEqual(escapeHtml('&'), '&amp;');
  assert.strictEqual(escapeHtml('<'), '&lt;');
  assert.strictEqual(escapeHtml('>'), '&gt;');
  assert.strictEqual(escapeHtml('"'), '&quot;');
  assert.strictEqual(escapeHtml("'"), '&#39;');
  assert.strictEqual(escapeHtml(''), '');
  assert.strictEqual(escapeHtml('plain text'), 'plain text');
  // The ampersand of an entity this function produced is never escaped twice.
  assert.strictEqual(escapeHtml('a < b'), 'a &lt; b');
  assert.strictEqual(escapeHtml('&lt;'), '&amp;lt;');
  assert.strictEqual(escapeHtml('&amp;'), '&amp;amp;');
  // A realistic injection attempt comes back inert.
  assert.strictEqual(
    escapeHtml('<script>alert("x" + \'y\')</script>'),
    '&lt;script&gt;alert(&quot;x&quot; + &#39;y&#39;)&lt;/script&gt;'
  );
});

test('acronyms-configurable: titleCase takes a caller-supplied acronym set', () => {
  // The built-in list is still the default.
  assert.strictEqual(titleCase('the http api'), 'The HTTP API');
  // A caller's own set, as a Set or as an array.
  assert.strictEqual(titleCase('the npm cli', new Set(['NPM', 'CLI'])), 'The NPM CLI');
  assert.strictEqual(titleCase('the npm cli', ['NPM', 'CLI']), 'The NPM CLI');
  // A supplied set replaces the default rather than extending it.
  assert.strictEqual(titleCase('the http api', ['NPM']), 'The Http Api');
  // Matching is case-insensitive and the caller's own spelling is what comes out —
  // so 'iOS' stays 'iOS' and a lowercase entry prints lowercase.
  assert.strictEqual(titleCase('the ios app', ['iOS']), 'The iOS App');
  assert.strictEqual(titleCase('the NPM cli', ['npm']), 'The npm Cli');
  // Passing a custom set does not mutate the built-in default.
  assert.strictEqual(titleCase('the http api'), 'The HTTP API');
});

test('excerpt: first maxWords words, ellipsis only when cut', () => {
  assert.strictEqual(excerpt('one two three four five', 3), 'one two three…');
  // Not cut: returned unchanged, no ellipsis — including the exact-fit case.
  assert.strictEqual(excerpt('one two three', 3), 'one two three');
  assert.strictEqual(excerpt('one two three', 5), 'one two three');
  assert.strictEqual(excerpt('', 5), '');
  assert.strictEqual(excerpt('  padded  text  ', 5), '  padded  text  ');
  // Line breaks and runs of whitespace collapse in the cut form.
  assert.strictEqual(excerpt('one\ntwo   three four', 2), 'one two…');
  assert.strictEqual(excerpt('one two three', 0), '…');
});

